# chacune avec son cours, l'essentiel, un exemple et un exercice d'application noté.
from notions_prog import C

def N(prog, nid, title, cours, essentiel, ex, steps):
    return C(prog, nid, cours, essentiel, [ex], title + ".", steps, title=title)

